<?php

class Mixbuild {

  /**
   * Run a function and capture its output.
   *
   * @param callable $callback
   * @return string
   *   Any output generated by the function
   */
  public static function capture($callback, ...$args): string {
    ob_start();
    try {
      $callback(...$args);
    }
    finally {
      $output = ob_get_clean();
    }
    return $output;
  }

  /**
   * @return string
   */
  public static function findCivicrmRoot(): string {
    return dirname(__DIR__, 3);
  }

  public static function printData($data, string $prefix = '  '): void {
    switch (gettype($data)) {
      case 'array':
        $isNumericArray = (range(0, count($data) - 1) == array_keys($data));
        echo "[\n";
        foreach ($data as $key => $value) {
          echo $prefix;
          if (!$isNumericArray) {
            static::printData($key);
            echo ' => ';
          }
          static::printData($value, $prefix . '  ');
          echo ",\n";
        }
        echo "]";
        break;

      default:
        var_export($data);
    }
  }

  public static function printFilteredClass(string $srcClass, $srcFilter = NULL): void {
    $srcFile = str_replace('_', '/', $srcClass) . '.php';
    $srcLines = explode("\n", file_get_contents(Mixbuild::findCivicrmRoot() . '/' . $srcFile));

    // Skip initial <?php declaration
    array_shift($srcLines);

    // Add a header
    array_unshift($srcLines, "// SOURCE: $srcFile\n");

    if ($srcFilter) {
      $srcLines = array_map($srcFilter, $srcLines);
    }

    echo "// @codingStandardsIgnoreStart\n";
    echo implode("\n", $srcLines);
    echo "// @codingStandardsIgnoreEnd\n";
  }

  public static function printFunction(ReflectionFunctionAbstract $function): void {
    $srcFile = $function->getFileName();
    $srcLines = explode("\n", file_get_contents($srcFile));
    $funcLines = array_slice($srcLines, $function->getStartLine() - 1, $function->getEndLine() - $function->getStartLine() + 1);
    $funcLines[0] = preg_replace(';( public| protected| static)+;','', $funcLines[0]);

    echo "// @codingStandardsIgnoreStart\n";
    echo implode("\n", $funcLines) . "\n\n";
    echo "// @codingStandardsIgnoreEnd\n";
  }

  public static function printDocblock(string $comment, array $annotations): void {
    printf("/**\n");
    foreach (explode("\n", $comment) as $line) {
      printf(" * %s\n", $line);
    }
    foreach ($annotations as $key => $value) {
      printf(" * @%s %s\n", $key, $value);
    }
    printf(" */\n");
  }

  /**
   * @param array $headers
   */
  public static function printEmptyMixin(): void {
    printf("return function(\$mixInfo, \$bootCache) {\n");
    printf("};\n");
  }

  /**
   * @param array $classMap
   *   Ex: ['AliasClass' => 'OriginalClass']
   */
  public static function registerClassAliases(array $classMap) {
    spl_autoload_register(function($requestedClass) use ($classMap) {
      if (isset($classMap[$requestedClass])) {
        class_alias($classMap[$requestedClass], $requestedClass);
      }
    });
  }


}
